    10→  computeStartSlotAtEpoch,
    11→  getBlockHeaderProposerSignatureSet,
    12→} from "@lodestar/state-transition";
    13→import {BlobIndex, Root, Slot, SubnetID, deneb, ssz} from "@lodestar/types";
    14→import {toRootHex, verifyMerkleBranch} from "@lodestar/utils";
    15→import {kzg} from "../../util/kzg.js";
    16→import {BlobSidecarErrorCode, BlobSidecarGossipError, BlobSidecarValidationError} from "../errors/blobSidecarError.js";
    17→import {GossipAction} from "../errors/gossipValidation.js";
    18→import {IBeaconChain} from "../interface.js";
    19→import {RegenCaller} from "../regen/index.js";
    20→
    21→export async function validateGossipBlobSidecar(
    22→  fork: ForkName,
    23→  chain: IBeaconChain,
    24→  blobSidecar: deneb.BlobSidecar,
    25→  subnet: SubnetID
    26→): Promise<void> {
    27→  const blobSlot = blobSidecar.signedBlockHeader.message.slot;
    28→
    29→  // [REJECT] The sidecar's index is consistent with `MAX_BLOBS_PER_BLOCK` -- i.e. `blob_sidecar.index < MAX_BLOBS_PER_BLOCK`.
    30→  const maxBlobsPerBlock = chain.config.getMaxBlobsPerBlock(computeEpochAtSlot(blobSlot));
    31→  if (blobSidecar.index >= maxBlobsPerBlock) {
    32→    throw new BlobSidecarGossipError(GossipAction.REJECT, {
    33→      code: BlobSidecarErrorCode.INDEX_TOO_LARGE,
    34→      blobIdx: blobSidecar.index,
    35→      maxBlobsPerBlock,
    36→    });
    37→  }
    38→
    39→  // [REJECT] The sidecar is for the correct subnet -- i.e. `compute_subnet_for_blob_sidecar(sidecar.index) == subnet_id`.
    40→  if (computeSubnetForBlobSidecar(fork, chain.config, blobSidecar.index) !== subnet) {
    41→    throw new BlobSidecarGossipError(GossipAction.REJECT, {
    42→      code: BlobSidecarErrorCode.INVALID_INDEX,
    43→      blobIdx: blobSidecar.index,
    44→      subnet,
    45→    });
    46→  }
    47→
    48→  // [IGNORE] The sidecar is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance) --
    49→  // i.e. validate that sidecar.slot <= current_slot (a client MAY queue future blocks for processing at
    50→  // the appropriate slot).
    51→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    52→  if (currentSlotWithGossipDisparity < blobSlot) {
    53→    throw new BlobSidecarGossipError(GossipAction.IGNORE, {
    54→      code: BlobSidecarErrorCode.FUTURE_SLOT,
    55→      currentSlot: currentSlotWithGossipDisparity,
    56→      blockSlot: blobSlot,
    57→    });
    58→  }
    59→
    60→  // [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
    61→  // sidecar.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    62→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    63→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    64→  if (blobSlot <= finalizedSlot) {
    65→    throw new BlobSidecarGossipError(GossipAction.IGNORE, {
    66→      code: BlobSidecarErrorCode.WOULD_REVERT_FINALIZED_SLOT,
    67→      blockSlot: blobSlot,
    68→      finalizedSlot,
    69→    });
    70→  }
    71→
    72→  // Check if the block is already known. We know it is post-finalization, so it is sufficient to check the fork choice.
    73→  //
    74→  // In normal operation this isn't necessary, however it is useful immediately after a
    75→  // reboot if the `observed_block_producers` cache is empty. In that case, without this
    76→  // check, we will load the parent and state from disk only to find out later that we
    77→  // already know this block.
    78→  const blockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(blobSidecar.signedBlockHeader.message);
