   110→      parentSlot: parentBlock.slot,
   111→      slot: blobSlot,
   112→    });
   113→  }
   114→
   115→  // getBlockSlotState also checks for whether the current finalized checkpoint is an ancestor of the block.
   116→  // As a result, we throw an IGNORE (whereas the spec says we should REJECT for this scenario).
   117→  // this is something we should change this in the future to make the code airtight to the spec.
   118→  // [IGNORE] The block's parent (defined by block.parent_root) has been seen (via both gossip and non-gossip sources) (a client MAY queue blocks for processing once the parent block is retrieved).
   119→  // [REJECT] The block's parent (defined by block.parent_root) passes validation.
   120→  const blockState = await chain.regen
   121→    .getBlockSlotState(parentRoot, blobSlot, {dontTransferCache: true}, RegenCaller.validateGossipBlock)
   122→    .catch(() => {
   123→      throw new BlobSidecarGossipError(GossipAction.IGNORE, {code: BlobSidecarErrorCode.PARENT_UNKNOWN, parentRoot});
   124→    });
   125→
   126→  // [REJECT] The proposer signature, signed_beacon_block.signature, is valid with respect to the proposer_index pubkey.
   127→  const signatureSet = getBlockHeaderProposerSignatureSet(blockState, blobSidecar.signedBlockHeader);
   128→  // Don't batch so verification is not delayed
   129→  if (!(await chain.bls.verifySignatureSets([signatureSet], {verifyOnMainThread: true}))) {
