   154→  // a case _do not_ `REJECT`, instead `IGNORE` this message.
   155→  const proposerIndex = blobSidecar.signedBlockHeader.message.proposerIndex;
   156→  if (blockState.epochCtx.getBeaconProposer(blobSlot) !== proposerIndex) {
   157→    throw new BlobSidecarGossipError(GossipAction.REJECT, {
   158→      code: BlobSidecarErrorCode.INCORRECT_PROPOSER,
   159→      proposerIndex,
   160→    });
   161→  }
   162→
   163→  // blob, proof and commitment as a valid BLS G1 point gets verified in batch validation
   164→  try {
