   169→      blobIdx: blobSidecar.index,
   170→    });
   171→  }
   172→}
   173→
   174→/**
   175→ * Validate some blob sidecars in a block
   176→ *
   177→ * Requires the block to be known to the node
   178→ */
   179→export async function validateBlockBlobSidecars(
   180→  blockSlot: Slot,
   181→  blockRoot: Root,
   182→  blockBlobCount: number,
   183→  blobSidecars: deneb.BlobSidecars
   184→): Promise<void> {
   185→  if (blobSidecars.length === 0) {
   186→    return;
   187→  }
   188→
   189→  if (blockBlobCount === 0) {
   190→    throw new BlobSidecarValidationError({
   191→      code: BlobSidecarErrorCode.INCORRECT_SIDECAR_COUNT,
   192→      slot: blockSlot,
   193→      expected: blockBlobCount,
   194→      actual: blobSidecars.length,
   195→    });
   196→  }
   197→
   198→  // Hash the first sidecar block header and compare the rest via (cheaper) equality
   199→  const firstSidecarBlockHeader = blobSidecars[0].signedBlockHeader.message;
   200→  const firstBlockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(firstSidecarBlockHeader);
   201→  if (Buffer.compare(blockRoot, firstBlockRoot) !== 0) {
   202→    throw new BlobSidecarValidationError(
   203→      {
   204→        code: BlobSidecarErrorCode.INCORRECT_BLOCK,
   205→        slot: blockSlot,
   206→        blobIdx: 0,
   207→        expected: toRootHex(blockRoot),
   208→        actual: toRootHex(firstBlockRoot),
   209→      },
   210→      "BlobSidecar doesn't match corresponding block"
   211→    );
   212→  }
   213→
   214→  const commitments = [];
   215→  const blobs = [];
   216→  const proofs = [];
   217→  for (const blobSidecar of blobSidecars) {
   218→    const blobIdx = blobSidecar.index;
   219→    if (!ssz.phase0.BeaconBlockHeader.equals(blobSidecar.signedBlockHeader.message, firstSidecarBlockHeader)) {
   220→      throw new BlobSidecarValidationError(
   221→        {
   222→          code: BlobSidecarErrorCode.INCORRECT_BLOCK,
   223→          slot: blockSlot,
   224→          blobIdx,
   225→          expected: toRootHex(blockRoot),
   226→          actual: "unknown - compared via equality",
   227→        },
   228→        "BlobSidecar doesn't match corresponding block"
   229→      );
   230→    }
   231→
   232→    if (!validateBlobSidecarInclusionProof(blobSidecar)) {
   233→      throw new BlobSidecarValidationError(
   234→        {
   235→          code: BlobSidecarErrorCode.INCLUSION_PROOF_INVALID,
   236→          slot: blockSlot,
   237→          blobIdx,
   238→        },
   239→        "BlobSidecar inclusion proof invalid"
   240→      );
   241→    }
   242→
   243→    commitments.push(blobSidecar.kzgCommitment);
   244→    blobs.push(blobSidecar.blob);
   245→    proofs.push(blobSidecar.kzgProof);
