   268→
   269→export async function validateBlobsAndBlobProofs(
   270→  expectedKzgCommitments: deneb.BlobKzgCommitments,
   271→  blobs: deneb.Blobs,
   272→  proofs: deneb.KZGProofs
   273→): Promise<void> {
   274→  // assert verify_aggregate_kzg_proof(blobs, expected_kzg_commitments, kzg_aggregated_proof)
   275→  let isProofValid: boolean;
   276→  try {
   277→    isProofValid = await kzg.asyncVerifyBlobKzgProofBatch(blobs, expectedKzgCommitments, proofs);
   278→  } catch (e) {
   279→    (e as Error).message = `Error on verifyBlobKzgProofBatch: ${(e as Error).message}`;
   280→    throw e;
   281→  }
   282→  if (!isProofValid) {
   283→    throw Error("Invalid verifyBlobKzgProofBatch");
   284→  }
   285→}
   286→
   287→export function validateBlobSidecarInclusionProof(blobSidecar: deneb.BlobSidecar): boolean {
   288→  return verifyMerkleBranch(
   289→    ssz.deneb.KZGCommitment.hashTreeRoot(blobSidecar.kzgCommitment),
   290→    blobSidecar.kzgCommitmentInclusionProof,
   291→    KZG_COMMITMENT_INCLUSION_PROOF_DEPTH,
   292→    KZG_COMMITMENT_SUBTREE_INDEX0 + blobSidecar.index,
   293→    blobSidecar.signedBlockHeader.message.bodyRoot
   294→  );
   295→}
